insert into public.ce_course1_catalog(id,metadata) values('1047239','{"id": "1047239", "title": "A Medication Review for the Experienced CRNA", "credits": 20.0, "module_count": 11, "planned_price_usd": 249.99, "course_bonus_months": 1, "bundle_bonus_months": 3, "bonus_policy": "One course bonus and one bundle bonus per account, once each across stores. Benefit windows begin on verified purchase dates and overlap rather than stack. No automatic subscription enrollment; existing store subscription billing is unchanged.", "approval_statement": "This program has been prior approved by the American Association of Nurse Anesthesiology for 20.00 MAC Ed CE credits; Code Number 1047239; Expiration Date 9/30/2029.", "pharmacology_statement": "The American Association of Nurse Anesthesiology designates this program as meeting the criteria for up to 17.50 CE credits in Pharmacology & Therapeutics.", "pain_statement": "The American Association of Nurse Anesthesiology designates this program as meeting the criteria for up to 2.50 CE credits in Pain Management.", "starts": "2026-10-01", "expires": "2029-09-30", "contact": "info@cehalo.com", "module": {"id": "course_1_module_1", "title": "Ketamine & Anesthesia", "credits": 2.0, "pharmacology_credits": 1.5, "pain_credits": 0.5, "objectives": ["Describe ketamine’s primary mechanism as a noncompetitive NMDA-receptor antagonist and identify its secondary receptor and channel interactions relevant to CRNA practice.", "Compare the hemodynamic, respiratory, and analgesic profile of racemic ketamine and S-ketamine (esketamine) across induction, procedural sedation, subanesthetic infusion, and ICU analgosedation contexts.", "Select and titrate an appropriate ketamine regimen for a specific perioperative or critical-care scenario using current evidence-based dose ranges (bolus, subanesthetic infusion, PCA adjunct, intranasal).", "Anticipate, prevent, and manage ketamine-associated adverse effects — including emergence phenomena, hallucinations, hypersalivation, tachycardia, hypertension, and dissociative recovery — in at-risk populations (PTSD, active psychosis, elderly, cardiovascular disease).", "Apply current AANA, ASRA/AAPM/ASA, and multi-society consensus guidance when integrating ketamine into multimodal, opioid-sparing perioperative and chronic pain pathways.", "Evaluate the strength and limitations of recent (2024–2026) evidence regarding perioperative and ICU ketamine — including neutral and negative trials such as IMPAKT ERAS — to inform balanced, patient-centered clinical decisions."], "evaluation_items": ["The facilitator was effective in presenting the material.", "Teaching methods were effective.", "Online learning format facilitated learning.", "The content was related to the objectives.", "My personal learning objectives were met."], "question_count": 15, "bank_size": 25, "passing_score": 12, "max_attempts": 3, "document_sha256": "9f66d7c49006d02297dd6c27113ce0ebd15f377202f1665cd3b7b108617dc8e6"}}'::jsonb) on conflict(id) do update set metadata=excluded.metadata;
insert into public.ce_course1_resources(id,data) values('ketamine_questions','[{"module_id": "course_1_module_1", "stem": "Ketamine''s primary mechanism of anesthetic action is best described as:", "choice_a": "Noncompetitive antagonism at the NMDA receptor", "choice_b": "GABA-A receptor potentiation", "choice_c": "μ-opioid receptor agonism", "choice_d": "α-2 adrenergic agonism", "correct_choice": "a", "rationale": "Ketamine attenuates glutamatergic excitatory transmission by noncompetitively blocking the NMDA receptor (Duong et al., 2026).", "difficulty": "medium", "question_number": 1, "question_id": "course_1_module_1_q01", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "A CRNA plans a subanesthetic ketamine infusion for opioid-sparing analgesia during major spine surgery. Which dose range is most consistent with current evidence?", "choice_a": "0.001–0.01 mg/kg/hr", "choice_b": "0.06–0.5 mg/kg/hr after a 0.25–0.5 mg/kg bolus", "choice_c": "1.0–2.0 mg/kg/hr", "choice_d": "0.5 mg/kg every 3 min IV push", "correct_choice": "b", "rationale": "Subanesthetic perioperative infusion: 0.5 mg/kg bolus followed by 0.06–0.5 mg/kg/hr (George & Johns, 2020; Schwenk et al., 2018).", "difficulty": "medium", "question_number": 2, "question_id": "course_1_module_1_q02", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "Which physiologic effect is most typical after IV induction with ketamine 1.5 mg/kg in a hemodynamically normal adult?", "choice_a": "Bradycardia and hypotension", "choice_b": "Increased heart rate and blood pressure", "choice_c": "Profound respiratory depression requiring immediate intubation", "choice_d": "Bronchoconstriction", "correct_choice": "b", "rationale": "Ketamine causes indirect sympathomimetic effect via monoaminergic reuptake inhibition — HR and BP rise; respiration is comparatively preserved; bronchodilation is common (Duong et al., 2026).", "difficulty": "medium", "question_number": 3, "question_id": "course_1_module_1_q03", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "Norketamine is best described as:", "choice_a": "An inactive metabolite excreted unchanged in urine", "choice_b": "An active metabolite contributing ongoing analgesia after ketamine is stopped", "choice_c": "A CYP inhibitor that prolongs opioid effect", "choice_d": "A precursor that must be converted to ketamine to be active", "correct_choice": "b", "rationale": "Hepatic biotransformation yields norketamine, an active metabolite with ongoing analgesic activity and a plasma half-life of 5–6 h (Duong et al., 2026).", "difficulty": "medium", "question_number": 4, "question_id": "course_1_module_1_q04", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "According to the 2025 multinational Rapid Practice Guideline (Amer et al., 2025), the panel recommended:", "choice_a": "Ketamine monotherapy over propofol for all mechanically ventilated ICU adults", "choice_b": "Against ketamine monotherapy and for adjunctive ketamine when other agents are available", "choice_c": "Ketamine only for pediatric ICU patients", "choice_d": "Ketamine be avoided entirely in the ICU", "correct_choice": "b", "rationale": "The RPG issued two conditional recommendations: against monotherapy analgo-sedation and for adjunctive ketamine to opioids ± propofol ± dexmedetomidine (Amer et al., 2025).", "difficulty": "medium", "question_number": 5, "question_id": "course_1_module_1_q05", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "The IMPAKT ERAS trial (Raymond et al., 2025) reported which key finding for perioperative ketamine in abdominal ERAS?", "choice_a": "Significant reduction in length of stay", "choice_b": "50% reduction in opioid consumption", "choice_c": "No benefit and increased debilitating dizziness and hallucinations", "choice_d": "Reduced ICU transfer rate", "correct_choice": "c", "rationale": "IMPAKT ERAS found no LOS or opioid benefit; ICU transfer increased (OR 2.03), dizziness (OR 6.05), and hallucinations (OR 2.69) all rose (Raymond et al., 2025).", "difficulty": "medium", "question_number": 6, "question_id": "course_1_module_1_q06", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "A 62-year-old male with a history of well-controlled schizophrenia and hypertension is scheduled for laparoscopic cholecystectomy. The most appropriate ketamine plan is:", "choice_a": "Bolus 1 mg/kg at induction plus 0.5 mg/kg/hr infusion for 48 h", "choice_b": "Avoid subanesthetic ketamine or use only minimal doses with psychiatric input; document rationale", "choice_c": "Full-dose induction with ketamine to avoid opioids entirely", "choice_d": "Intranasal 1 mg/kg for postoperative breakthrough pain", "correct_choice": "b", "rationale": "Active or unstable psychosis is a relative contraindication. Cautious minimal dosing with psychiatric input is appropriate; large perioperative infusions carry disproportionate psychotomimetic risk (Raymond et al., 2025).", "difficulty": "medium", "question_number": 7, "question_id": "course_1_module_1_q07", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "Which adverse effect is most likely to be attenuated by prophylactic glycopyrrolate 0.1–0.2 mg IV before ketamine administration?", "choice_a": "Emergence hallucinations", "choice_b": "Tachycardia", "choice_c": "Hypersalivation", "choice_d": "Post-operative nausea", "correct_choice": "c", "rationale": "Ketamine causes muscarinic antagonism and reflex hypersalivation; glycopyrrolate is a targeted antisialagogue (George & Johns, 2020).", "difficulty": "medium", "question_number": 8, "question_id": "course_1_module_1_q08", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "For chronic refractory neuropathic pain, current expert-consensus guidance (Cohen et al., 2018; Pickering et al., 2026) recommends ketamine be considered:", "choice_a": "First-line therapy", "choice_b": "A non–first-line option for refractory pain, initiated at ~80 mg over ≥2 h, within a structured monitoring program", "choice_c": "Only via intranasal route for outpatient use", "choice_d": "As a permanent oral regimen", "correct_choice": "b", "rationale": "Ketamine is not first-line for chronic pain. Consensus guidance recommends 80 mg IV over ≥2 h as an initial regimen, escalating by response (Cohen et al., 2018; Pickering et al., 2026).", "difficulty": "medium", "question_number": 9, "question_id": "course_1_module_1_q09", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "Perioperative esketamine''s most consistently demonstrated benefit in the 2025 BMJ Open meta-analysis (Su et al.) was:", "choice_a": "Reduction in 3-month post-op cognitive impairment", "choice_b": "Reduction in postoperative delirium and delayed neurocognitive recovery", "choice_c": "Reduction in surgical bleeding", "choice_d": "Reduction in intraoperative hypotension", "correct_choice": "b", "rationale": "Su et al. 2025 found POD RR 0.46 (95% CI 0.30–0.71) and dNCR RR 0.41 (95% CI 0.21–0.78), with no significant 3-month effect.", "difficulty": "medium", "question_number": 10, "question_id": "course_1_module_1_q10", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "Which dose range best matches ketamine primary analgosedation in the 2024 surgical/trauma ICU cohort (Peters et al.)?", "choice_a": "1–2 mg/kg/hr", "choice_b": "Median 0.18 mg/kg/hr (0.1–0.3)", "choice_c": "0.02 mg/kg/hr", "choice_d": "0.6 mg/kg/hr", "correct_choice": "b", "rationale": "Peters et al. 2024 reported median 0.18 mg/kg/hr (IQR 0.1–0.3) over median 30 h; 88% avoided a concomitant opioid infusion.", "difficulty": "medium", "question_number": 11, "question_id": "course_1_module_1_q11", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "A CRNA anticipates an obstetric emergency requiring rapid analgesia when regional anesthesia is contraindicated. The most defensible ketamine option is:", "choice_a": "Subanesthetic 0.15–0.3 mg/kg IV with neonatal monitoring if delivery is within 1 h", "choice_b": "3 mg/kg IV induction dose", "choice_c": "Continuous 1 mg/kg/hr infusion for 24 h", "choice_d": "Ketamine is absolutely contraindicated in pregnancy", "correct_choice": "a", "rationale": "Ketamine can be used in obstetric analgesia when other options are contraindicated; subanesthetic doses with neonatal monitoring are appropriate (Duong et al., 2026).", "difficulty": "medium", "question_number": 12, "question_id": "course_1_module_1_q12", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "An 82-year-old is scheduled for orthopedic surgery. Compared with a 35-year-old at the same body weight, the CRNA should:", "choice_a": "Increase ketamine dose by 25%", "choice_b": "Reduce ketamine dose by 25–50% and titrate slowly", "choice_c": "Use a fixed 100 mg IV bolus regardless of age", "choice_d": "Avoid all opioid-sparing strategies", "correct_choice": "b", "rationale": "Age ≥65 y is a monitoring precaution; lower doses and slower titration reduce dizziness, prolonged emergence, and delirium (George & Johns, 2020).", "difficulty": "medium", "question_number": 13, "question_id": "course_1_module_1_q13", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "Continuous end-tidal CO₂ monitoring is most strongly indicated during ketamine administration when:", "choice_a": "Ketamine is used alone in a healthy adult", "choice_b": "Ketamine is combined with concurrent opioid or benzodiazepine, or the patient is at high respiratory risk", "choice_c": "Ketamine dose is under 0.1 mg/kg", "choice_d": "The patient is under 40 years old", "correct_choice": "b", "rationale": "Ketamine alone rarely causes clinically important respiratory depression, but co-administered opioids/benzodiazepines or baseline respiratory risk raise the risk (Goordeen et al., 2022).", "difficulty": "medium", "question_number": 14, "question_id": "course_1_module_1_q14", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "Which of the following most accurately reflects ketamine''s effect on 24-hour postoperative opioid consumption after laparoscopic cholecystectomy (Akram et al., 2026)?", "choice_a": "Increased by ~5 mg morphine equivalents", "choice_b": "Reduced by ~4–5 mg morphine equivalents (ketamine subgroup MD −5.35)", "choice_c": "No change", "choice_d": "Reduced by 50 mg morphine equivalents", "correct_choice": "b", "rationale": "Meta-analysis MD −4.10 mg (overall), ketamine subgroup MD −5.35 mg; very-low-certainty evidence (Akram et al., 2026).", "difficulty": "medium", "question_number": 15, "question_id": "course_1_module_1_q15", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "According to the SFAR postoperative-pain recommendations, when should an intraoperative ketamine infusion used as an analgesic adjunct be stopped?", "choice_a": "At the moment of extubation", "choice_b": "Approximately 30 minutes before the anticipated end of surgery", "choice_c": "Exactly 60 minutes before extubation in every patient", "choice_d": "Only after discharge from the PACU", "correct_choice": "b", "rationale": "The SFAR recommendations specify stopping the infusion 30 minutes before the end of surgery (Aubrun et al., 2019). This is a source-specific recommendation, not a universal requirement or proof that 30 minutes is superior to 60 minutes for every patient. ASRA/AAPM/ASA acute-pain guidance describes regimens stopped at surgery completion and others continued postoperatively; timing depends on the clinical indication and protocol (Schwenk et al., 2018).", "difficulty": "medium", "source_urls": ["https://sfar.org/wp-content/uploads/2019/10/rfe-revision-of-expert-panel-guidelines-on-postoperative-pain-management.pdf", "https://pmc.ncbi.nlm.nih.gov/articles/PMC6023582/"], "question_number": 16, "question_id": "course_1_module_1_q16"}, {"module_id": "course_1_module_1", "stem": "For emergency-department chemical restraint of an acutely agitated adult, the mean parenteral ketamine dose (Peter et al., 2025) most often used was:", "choice_a": "IM ≈ 3.83 mg/kg or IV ≈ 2.09 mg/kg", "choice_b": "IN 5 mg/kg", "choice_c": "Oral 0.5 mg/kg", "choice_d": "IM 10 mg/kg", "correct_choice": "a", "rationale": "Peter et al. 2025 systematic review: IM mean 3.83 mg/kg; IV mean 2.09 mg/kg; sedation ~6 min; 24.5% required rescue dose.", "difficulty": "medium", "question_number": 17, "question_id": "course_1_module_1_q17", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "Which cardiovascular response is a concern when ketamine is administered to a critically ill patient with depleted catecholamine reserves?", "choice_a": "Guaranteed increases in blood pressure and cardiac output", "choice_b": "Direct myocardial depression with possible hemodynamic deterioration", "choice_c": "Selective pulmonary vasodilation without systemic effects", "choice_d": "Complete absence of cardiovascular effects at anesthetic doses", "correct_choice": "b", "rationale": "Ketamine''s indirect sympathetic effects usually increase heart rate and blood pressure, but its direct negative inotropic effect may become clinically apparent in catecholamine-depleted patients. Do not assume that ketamine will reliably improve blood pressure or cardiac output in this setting; assess hemodynamics and titrate with appropriate support (Cohen et al., 2018).", "difficulty": "medium", "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC6023575/"], "question_number": 18, "question_id": "course_1_module_1_q18"}, {"module_id": "course_1_module_1", "stem": "Which of the following is a MODERATE-certainty finding from Xu et al. (2026) regarding esketamine and ERAS?", "choice_a": "Complete elimination of postoperative pain", "choice_b": "Improvement in postoperative nausea/vomiting and early sleep quality within 72 h", "choice_c": "Reduction of mortality by 50%", "choice_d": "Elimination of postoperative depression", "correct_choice": "b", "rationale": "Xu et al. 2026 rated evidence for esketamine-associated improvement in PONV and early sleep as moderate-certainty; other outcomes remain low or insufficient.", "difficulty": "medium", "question_number": 19, "question_id": "course_1_module_1_q19", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "A CRNA reviewing risks with a patient before an outpatient ketamine infusion for CRPS should specifically mention which of the following, per Goordeen et al. (2022)?", "choice_a": "The infusion will cure the pain permanently", "choice_b": "Most side effects are transient (>95%) and resolve after discontinuation", "choice_c": "No side effects have been reported", "choice_d": "The infusion requires no monitoring", "correct_choice": "b", "rationale": "ASRA News (Goordeen et al., 2022) states >95% of side effects are transient and resolve after discontinuation; monitoring HR, BP, SpO₂, LOC, and EtCO₂ in high-risk patients is required.", "difficulty": "medium", "question_number": 20, "question_id": "course_1_module_1_q20", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "Which of the following is the most accurate statement regarding ketamine and respiratory drive?", "choice_a": "Ketamine reliably eliminates spontaneous respiration and requires immediate mechanical ventilation", "choice_b": "Ketamine typically preserves respiratory drive and often provides bronchodilation", "choice_c": "Ketamine is a potent bronchoconstrictor", "choice_d": "Ketamine reduces functional residual capacity by 50%", "correct_choice": "b", "rationale": "Ketamine is comparatively respiratory-sparing; bronchodilation is a well-recognized clinical feature useful in status asthmaticus (Duong et al., 2026).", "difficulty": "medium", "question_number": 21, "question_id": "course_1_module_1_q21", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "A patient with chronic hepatitis is being considered for repeated, high-dose ketamine infusions for refractory pain. Which additional safety measure is most appropriate?", "choice_a": "Omit laboratory monitoring if the first infusion was tolerated", "choice_b": "Use serum ketamine concentrations as the only safety assessment", "choice_c": "Consider baseline and postinfusion liver function tests based on individual risk", "choice_d": "Check liver function only if the patient develops emergence agitation", "correct_choice": "c", "rationale": "The chronic-pain consensus recommends considering baseline and postinfusion liver function tests case by case in patients with baseline liver dysfunction, increased hepatic risk, or anticipated high-dose ketamine exposure at frequent intervals. This is a grade C recommendation with low-certainty evidence, not a requirement for identical testing after every brief perioperative dose (Cohen et al., 2018).", "difficulty": "medium", "source_urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC6023575/"], "question_number": 22, "question_id": "course_1_module_1_q22"}, {"module_id": "course_1_module_1", "stem": "Which of the following is TRUE about the ASRA/AAPM/ASA acute pain consensus (Schwenk et al., 2018) as it applies to CRNAs?", "choice_a": "Ketamine is prohibited as a stand-alone acute-pain agent", "choice_b": "Ketamine may be used as a stand-alone acute-pain treatment or as an adjunct to opioids", "choice_c": "Intranasal ketamine is not recognized as a route", "choice_d": "PCA ketamine is contraindicated", "correct_choice": "b", "rationale": "Schwenk et al. 2018 supports ketamine as stand-alone therapy, opioid adjunct, and (to a lesser extent) via the intranasal route, and addresses PCA use.", "difficulty": "medium", "question_number": 23, "question_id": "course_1_module_1_q23", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "A patient develops emergence agitation with visual hallucinations after ketamine sedation. The most evidence-supported intervention is:", "choice_a": "Immediate physostigmine 2 mg IV", "choice_b": "Low-dose midazolam (e.g., 0.02 mg/kg IV) plus a quiet recovery environment", "choice_c": "Naloxone 0.4 mg IV", "choice_d": "Flumazenil 0.2 mg IV", "correct_choice": "b", "rationale": "Low-dose midazolam and a quiet emergence environment are the standard interventions for ketamine emergence phenomena; naloxone and flumazenil are not indicated.", "difficulty": "medium", "question_number": 24, "question_id": "course_1_module_1_q24", "source_urls": []}, {"module_id": "course_1_module_1", "stem": "Which statement best captures the current position of ketamine in perioperative pain management, integrating 2024–2026 evidence?", "choice_a": "Universal routine ketamine infusion for all abdominal surgery", "choice_b": "A targeted opioid-sparing option whose benefit is real but context-dependent; patient selection, dose, and setting matter more than protocol", "choice_c": "Ketamine should replace all opioids in all surgeries", "choice_d": "Ketamine has been shown to have no perioperative role", "correct_choice": "b", "rationale": "Current evidence, including IMPAKT ERAS negative signal and consistent opioid-sparing meta-analyses, supports context-dependent, patient-selected use rather than routine protocolized administration (Raymond et al., 2025; Xu et al., 2026; Duong et al., 2026).", "difficulty": "medium", "question_number": 25, "question_id": "course_1_module_1_q25", "source_urls": []}]'::jsonb) on conflict(id) do update set data=excluded.data;
insert into public.ce_course1_resources(id,data) values('ketamine_pdf','{"base64": "", "sha256": "9f66d7c49006d02297dd6c27113ce0ebd15f377202f1665cd3b7b108617dc8e6", "mime": "application/pdf"}'::jsonb) on conflict(id) do update set data=excluded.data;
insert into public.ce_course1_reviewers(user_id) select id from auth.users where lower(email)='nmfetzer@me.com' and is_anonymous=false on conflict do nothing;
